class_name MovingPlatform
extends AnimatableBody2D

@export var move_offset: Vector2 = Vector2(200.0, 0.0)
@export var speed: float = 80.0

var _start_position: Vector2
var _target_position: Vector2
var _moving_to_target: bool = true


func _ready() -> void:
	_start_position = global_position
	_target_position = _start_position + move_offset


func _physics_process(delta: float) -> void:
	var destination := _target_position if _moving_to_target else _start_position
	global_position = global_position.move_toward(destination, speed * delta)

	if global_position.distance_to(destination) < 1.0:
		_moving_to_target = not _moving_to_target

# All'interno di player/player_crouch_state.gd

func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	player.move_and_slide()

	if not player.is_on_floor():
		transitioned.emit(self, "fall")
		return

	# Se preme salto mentre è accovacciato, scende dalla piattaforma a senso unico
	if Input.is_action_just_pressed("jump"):
		player.position.y += 2.0
		transitioned.emit(self, "fall")
		return

	if not Input.is_action_pressed("crouch"):
		var direction := Input.get_axis("move_left", "move_right")
		if direction != 0.0:
			transitioned.emit(self, "run")
		else:
			transitioned.emit(self, "idle")

class_name Ladder
extends Area2D


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


func _on_body_entered(body: Node2D) -> void:
	if "is_on_ladder" in body:
		body.is_on_ladder = true


func _on_body_exited(body: Node2D) -> void:
	if "is_on_ladder" in body:
		body.is_on_ladder = false

class_name PlayerClimbState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D
@export var climb_speed: float = 120.0


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("idle")
	player.velocity = Vector2.ZERO


func physics_update(_delta: float) -> void:
	# Se il personaggio è uscito dall'area della scala, torna a cadere
	if not player.is_on_ladder:
		transitioned.emit(self, "fall")
		return

	# Calcolo direzione verticale: jump per salire, crouch per scendere
	var climb_direction := 0.0
	if Input.is_action_pressed("jump"):
		climb_direction -= 1.0
	if Input.is_action_pressed("crouch"):
		climb_direction += 1.0

	player.velocity.y = climb_direction * climb_speed

	# Permette un leggero spostamento laterale per staccarsi dalla scala
	var horizontal_direction := Input.get_axis("move_left", "move_right")
	player.velocity.x = horizontal_direction * (climb_speed * 0.8)

	player.move_and_slide()

	# Se scendendo tocca il pavimento, torna allo stato a riposo
	if player.is_on_floor() and climb_direction > 0.0:
		transitioned.emit(self, "idle")
		return

	# Salto rapido per staccarsi dalla scala
	if Input.is_action_just_pressed("jump") and horizontal_direction != 0.0:
		transitioned.emit(self, "jump")
